import { validateBody } from '@daz-pilot/backend-utils';
import {
	createOneSchoolBodySchema,
	updateMoodleConfigurationBodySchema,
	updateOidcConfigurationBodySchema,
} from '@daz-pilot/daz-pilot-backend-api-types';
import { Router } from 'express';
import {
	createOneSchoolController,
	getMoodleConfigurationController,
	getOidcConfigurationController,
	getRecentActivityController,
	updateMoodleConfigurationController,
	updateOidcConfigurationController,
} from '../controllers/school/schoolControllers.js';
import { authMiddleware } from '../middlewares/authMiddleware.js';

export const schoolRouter = Router();

schoolRouter.post(
	'/create-one-school',
	authMiddleware({ allowSuperAdmin: true }),
	validateBody(createOneSchoolBodySchema),
	createOneSchoolController,
);

schoolRouter.post(
	'/update-oidc-configuration',
	authMiddleware({ allowSuperAdmin: true, allowTeacher: { allowedRoles: ['admin'] } }),
	validateBody(updateOidcConfigurationBodySchema),
	updateOidcConfigurationController,
);

schoolRouter.post(
	'/get-oidc-configuration',
	authMiddleware({ allowTeacher: { allowedRoles: ['admin'] } }),
	getOidcConfigurationController,
);

